import { APIClient } from '../api/client.js';
import { RecallResult } from '../models/search.js';
import { logger } from '../utils/logger.js';
import { config } from '../config/index.js';

const api = new APIClient();

export const recallTools = [
  {
    name: 'recall_knowledge',
    description: 'Recall raw knowledge base entries without AI processing, returns original search results',
    parameters: {
      type: 'object',
      properties: {
        question: {
          type: 'string',
          description: 'The question to search for in the knowledge base'
        },
        topic_id: {
          type: 'string',
          description: 'Single knowledge base topic ID (alternative to topic_ids). If not provided, uses default from GET_NOTE_TOPIC_ID env var'
        },
        topic_ids: {
          type: 'array',
          items: { type: 'string' },
          description: 'Knowledge base topic IDs (currently supports only one). If not provided, uses default from GET_NOTE_TOPIC_ID env var'
        },
        top_k: {
          type: 'number',
          description: 'Number of top results to return',
          default: 10,
          minimum: 1,
          maximum: 50
        },
        intent_rewrite: {
          type: 'boolean',
          description: 'Enable intent rewriting for better search results',
          default: false
        },
        select_matrix: {
          type: 'boolean',
          description: 'Enable result reselection matrix',
          default: false
        },
        history: {
          type: 'array',
          items: {
            type: 'object',
            properties: {
              content: { type: 'string' },
              role: { type: 'string', enum: ['user', 'assistant'] }
            }
          },
          description: 'Conversation history for follow-up questions',
          default: []
        }
      },
      // 如果设置了默认topic_id，则不要求必需提供
      required: config.knowledgeBase.topicId ? ['question'] : ['question', 'topic_id']
    },
    handler: async (args) => {
      try {
        logger.info(`Recalling knowledge: ${args.question}`);
        
        // 确保至少有一个topic_id参数
        if (!args.topic_id && !args.topic_ids) {
          if (config.knowledgeBase.topicId) {
            args.topic_id = config.knowledgeBase.topicId;
            logger.info(`Using default topic_id: ${config.knowledgeBase.topicId}`);
          } else {
            throw new Error('Either topic_id or topic_ids is required, or set GET_NOTE_TOPIC_ID environment variable');
          }
        }
        
        const result = await api.recallKnowledge(args.question, {
          topic_id: args.topic_id,
          topic_ids: args.topic_ids,
          top_k: args.top_k || 10,
          intent_rewrite: args.intent_rewrite || false,
          select_matrix: args.select_matrix || false,
          history: args.history || []
        });
        
        const recallResult = new RecallResult(result);
        
        if (recallResult.items.length === 0) {
          return {
            content: [{
              type: 'text',
              text: 'No results found for the given query.'
            }]
          };
        }
        
        let content = `**Found ${recallResult.items.length} results:**\n\n`;
        
        recallResult.items.forEach((item, index) => {
          content += `**${index + 1}. ${item.title || 'Untitled'}**\n`;
          content += `**Type:** ${item.type} | **Score:** ${item.score.toFixed(4)} | **Source:** ${item.recallSource}\n`;
          content += `**Content:** ${item.content.substring(0, 300)}${item.content.length > 300 ? '...' : ''}\n`;
          content += `**ID:** ${item.id}\n\n`;
        });
        
        return {
          content: [{
            type: 'text',
            text: content
          }]
        };
      } catch (error) {
        logger.error(`Knowledge recall failed: ${error.message}`);
        throw error;
      }
    }
  },

  {
    name: 'recall_knowledge_detailed',
    description: 'Recall knowledge base entries with full content and metadata',
    parameters: {
      type: 'object',
      properties: {
        question: {
          type: 'string',
          description: 'The question to search for in the knowledge base'
        },
        topic_id: {
          type: 'string',
          description: 'Single knowledge base topic ID (alternative to topic_ids)'
        },
        topic_ids: {
          type: 'array',
          items: { type: 'string' },
          description: 'Knowledge base topic IDs (currently supports only one)'
        },
        top_k: {
          type: 'number',
          description: 'Number of top results to return',
          default: 5,
          minimum: 1,
          maximum: 20
        },
        intent_rewrite: {
          type: 'boolean',
          description: 'Enable intent rewriting for better search results',
          default: false
        },
        select_matrix: {
          type: 'boolean',
          description: 'Enable result reselection matrix',
          default: false
        }
      },
      // 如果设置了默认topic_id，则不要求必需提供
      required: config.knowledgeBase.topicId ? ['question'] : ['question', 'topic_id']
    },
    handler: async (args) => {
      try {
        logger.info(`Detailed knowledge recall: ${args.question}`);
        
        if (!args.topic_id && !args.topic_ids) {
          throw new Error('Either topic_id or topic_ids is required');
        }
        
        const result = await api.recallKnowledge(args.question, {
          topic_id: args.topic_id,
          topic_ids: args.topic_ids,
          top_k: args.top_k || 5,
          intent_rewrite: args.intent_rewrite || false,
          select_matrix: args.select_matrix || false
        });
        
        const recallResult = new RecallResult(result);
        
        if (recallResult.items.length === 0) {
          return {
            content: [{
              type: 'text',
              text: 'No results found for the given query.'
            }]
          };
        };

        // 返回结构化数据，便于其他工具处理
        const structuredData = {
          total: recallResult.items.length,
          items: recallResult.items.map(item => ({
            id: item.id,
            title: item.title,
            content: item.content,
            score: item.score,
            type: item.type,
            recall_source: item.recallSource
          }))
        };
        
        return {
          content: [{
            type: 'text',
            text: JSON.stringify(structuredData, null, 2)
          }]
        };
      } catch (error) {
        logger.error(`Detailed knowledge recall failed: ${error.message}`);
        throw error;
      }
    }
  }
];